inlineCssEdits.before:
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
background: rgba(255, 255, 255, 0.92);
border-radius: var(--gl-radius-md);
padding: 16px 10px 14px;
width: 100%;
height: 100%;
box-sizing: border-box;
transition: transform 0.25s ease, box-shadow 0.25s ease;
border: 1px solid rgba(var(--gl-color-primary-rgb), 0.06);
box-shadow: 0 2px 8px rgba(var(--gl-color-primary-rgb), 0.04);

inlineCssEdits.after:
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
background:transparent;
border-radius:0;
padding: 16px 10px 14px;
width: 100%;
height: 100%;
box-sizing: border-box;
transition:none;
border:0;
box-shadow:none;

